// 服务实现
// ═══════════════════════════════════════════════════════════════

export interface RealismEnhancement {
  propDetails: string[];
  physicsChains: string[];
  psychologyBehaviors: string[];
  expressionDetails: string[];
  combinedText: string;
}

/**
 * 智能关键词匹配：检查关键词是否在动作描述的合理上下文中
 * 避免误匹配（如"打电话"出现在"打电话给老板"的对话中，但镜头可能只是拿着电话说话）
 */
function smartMatch(text: string, keywords: string[]): boolean {
  for (const kw of keywords) {
    if (text.includes(kw)) {
      // 检查是否是否定语境（"不打电话""没打电话"）
      const negPatterns = ['不' + kw, '没' + kw, '没有' + kw, '别' + kw, '不要' + kw];
      if (negPatterns.some(p => text.includes(p))) continue;
      return true;
    }
  }
  return false;
}

/**
 * 冲突检测：检查增强内容是否和剧本描述冲突
 * 返回 true = 有冲突，应该跳过
 * 注意：不检测时代冲突（穿越剧需要古今混搭）
 */
function hasConflict(text: string, detail: string): boolean {
  // 检测角色性格冲突（冷静角色不应该有激烈反应）
  const calmPatterns = ['冷静', '沉稳', '内敛', '隐忍', '面瘫', '高冷', '面无表情'];
  const intensePatterns = ['摔门', '拍桌子', '大喊', '尖叫', '大哭', '暴怒', '砸东西'];
  
  const isCalm = calmPatterns.some(p => text.includes(p));
  const hasIntense = intensePatterns.some(p => detail.includes(p));
  
  if (isCalm && hasIntense) return true;
  
  return false;
}

/**
 * 根据镜头景别调整细节量
 * 远景/全景不需要微表情和道具细节
 * 特写/近景需要丰富的表情和道具细节
 */
function getDetailLevel(shotSize: string): 'minimal' | 'moderate' | 'full' {
  const size = (shotSize || '').toLowerCase();
  if (size.includes('特写') || size.includes('近景') || size.includes('close-up') || size.includes('closeup')) {
    return 'full'; // 特写需要最多细节
  }
  if (size.includes('中景') || size.includes('medium') || size.includes('中近')) {
    return 'moderate'; // 中景适中
  }
  return 'minimal'; // 远景/全景最少细节
}

/**
 * 分析镜头内容，生成四维真实性增强文本
 * 优化版：智能匹配 + 冲突检测 + 优先级管理 + 智能裁剪
 */
export function enhanceRealism(shotContext: DirectorShotContext): RealismEnhancement {
  const actionText = (shotContext.actionDescription || '').toLowerCase();
  const dialogueText = (shotContext.dialogue || '').toLowerCase();
  const moodText = (shotContext.mood || '').toLowerCase();
  const sceneText = (shotContext.sceneDescription || '').toLowerCase();
  const fullText = [actionText, dialogueText, moodText, sceneText].join(' ');
  
  // 根据景别决定细节量
  const detailLevel = getDetailLevel(shotContext.shotSize || '');
  
  const propDetails: string[] = [];
  const physicsChains: string[] = [];
  const psychologyBehaviors: string[] = [];
  const expressionDetails: string[] = [];

  // 1. 道具细节匹配（仅在动作描述中匹配，避免对话误匹配）
  for (const prop of PROP_DETAILS) {
    if (smartMatch(actionText, prop.keywords)) {
      if (hasConflict(fullText, prop.detail)) continue; // 冲突检测
      if (!propDetails.includes(prop.detail)) propDetails.push(prop.detail);
    }
  }

  // 2. 物理反应链匹配（动作描述 + 情绪）
  const actionMoodText = actionText + ' ' + moodText;
  for (const chain of PHYSICS_CHAINS) {
    if (smartMatch(actionMoodText, chain.actionKeywords)) {
      if (hasConflict(fullText, chain.chain)) continue;
      if (!physicsChains.includes(chain.chain)) physicsChains.push(chain.chain);
    }
  }

  // 3. 心理-行为映射匹配（情绪 + 动作描述）
  for (const pb of PSYCHOLOGY_BEHAVIORS) {
    if (smartMatch(moodText + ' ' + actionText, pb.psychologyKeywords)) {
      if (hasConflict(fullText, pb.behavior)) continue;
      if (!psychologyBehaviors.includes(pb.behavior)) psychologyBehaviors.push(pb.behavior);
    }
  }

  // 4. 表情细节匹配（情绪 + 动作描述，仅在非远景时启用）
  if (detailLevel !== 'minimal') {
    for (const exp of EXPRESSION_DETAILS) {
      if (smartMatch(moodText + ' ' + actionText, exp.keywords)) {
        if (hasConflict(fullText, exp.detail)) continue;
        if (!expressionDetails.includes(exp.detail)) expressionDetails.push(exp.detail);
      }
    }
  }

  // 根据景别智能裁剪数量
  let maxPerCategory: number;
  switch (detailLevel) {
    case 'full': maxPerCategory = 2; break;   // 特写：每类最多2条
    case 'moderate': maxPerCategory = 1; break; // 中景：每类最多1条
    default: maxPerCategory = 1; break;        // 远景：每类最多1条，且表情已跳过
  }
  
  // 总共最多4条（避免提示词过长）
  const totalMax = 4;
  let totalCount = 0;
  
  const parts: string[] = [];
  
  // 优先级：物理反应链 > 道具细节 > 心理-行为 > 表情细节
  const priorityOrder = [
    { label: '物理反应链', items: physicsChains, max: maxPerCategory },
    { label: '道具操作真实性', items: propDetails, max: maxPerCategory },
    { label: '心理-行为映射', items: psychologyBehaviors, max: 1 },
    { label: '表情细节', items: expressionDetails, max: detailLevel === 'full' ? 1 : 0 },
  ];
  
  for (const { label, items, max } of priorityOrder) {
    if (totalCount >= totalMax) break;
    const take = Math.min(max, items.length, totalMax - totalCount);
    if (take > 0) {
      parts.push(`═══════════ ${label}（参考细节，如与剧本冲突以剧本为准） ═══════════\n` + items.slice(0, take).join('\n\n'));
      totalCount += take;
    }
  }

  return {
    propDetails,
    physicsChains,
    psychologyBehaviors,
    expressionDetails,
    combinedText: parts.length > 0 ? '\n\n' + parts.join('\n\n') : '',
  };
}

export const actionRealismService = {
  enhanceRealism,
  PROP_DETAILS,
  PHYSICS_CHAINS,
  PSYCHOLOGY_BEHAVIORS,
  EXPRESSION_DETAILS,
};
